CREATE TABLE
  "city" (
    "id" BIGINT PRIMARY KEY,
    "name" text UNIQUE NOT NULL,
    "created_at" timestamp NOT NULL DEFAULT NOW (),
    "updated_at" timestamp
  );

CREATE TABLE
  "sport" (
    "id" BIGINT PRIMARY KEY NOT NULL,
    "name" varchar(31) NOT NULL,
    "sport_category" varchar(15) NOT NULL,
    "min_players_per_team" smallint NOT NULL,
    "max_players_per_team" smallint NOT NULL,
    "minutes_per_round" smallint NOT NULL,
    "minutes_per_pause" smallint NOT NULL,
    "num_referees_per_match" smallint NOT NULL
  );

CREATE TABLE
  "account" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "firebase_uid" varchar(255) UNIQUE,
    "stripe_id" varchar(255) UNIQUE,
    "username" varchar(15) UNIQUE NOT NULL,
    "email" varchar(255) UNIQUE NOT NULL,
    "phone" varchar(15) UNIQUE NOT NULL,
    "name" varchar(31) NOT NULL,
    "surname" varchar(31) NOT NULL,
    "vip" bool DEFAULT false NOT NULL,
    "vip_type" varchar(15) DEFAULT 'NONE' NOT NULL,
    "vip_start" date,
    "vip_end" date,
    "role" varchar(15) NOT NULL,
    "status" varchar(15) DEFAULT 'ACTIVE',
    "preferred_city_id" BIGINT,
    "image_url" varchar(511),
    "favorite_sport_category" varchar(15) NOT NULL DEFAULT 'FOOTBALL',
    "birthdate" date NOT NULL,
    "created_at" timestamp DEFAULT now (),
    "updated_at" timestamp,
    "last_login" timestamp DEFAULT now ()
  );

CREATE TABLE
  "player" (
    "player_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT UNIQUE NOT NULL,
    "points" int NOT NULL DEFAULT '0'
  );

CREATE TABLE
  "coordinator" (
    "coordinator_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT UNIQUE NOT NULL,
    "level" smallint NOT NULL DEFAULT 1
  );

CREATE TABLE
  "referee" (
    "referee_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT UNIQUE NOT NULL,
    "level" smallint NOT NULL DEFAULT 1
  );

CREATE TABLE
  "organization" (
    "organization_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT UNIQUE NOT NULL,
    "org_name" varchar(255) NOT NULL
  );

CREATE TABLE
  "account_restriction" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT NOT NULL,
    "type" varchar(31) NOT NULL,
    "valid_from" date NOT NULL,
    "valid_to" date,
    "created_at" timestamp NOT NULL DEFAULT NOW (),
    "updated_at" timestamp
  );

CREATE TABLE
  "friend_invite" (
    "invited_account_id" BIGINT PRIMARY KEY,
    "inviter_account_id" BIGINT NOT NULL,
    "redeemed" bool NOT NULL DEFAULT false,
    "inviter_transaction_id" BIGINT NOT NULL,
    "created_at" timestamp NOT NULL DEFAULT NOW (),
    "updated_at" timestamp
