CREATE TABLE
  "wallet" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT UNIQUE NOT NULL,
    --"prize_balance" numeric(10,2) NOT NULL DEFAULT 0,
    --"personal_balance" numeric(10,2) NOT NULL DEFAULT 0,
    --"invite_balance" numeric(10,2) NOT NULL DEFAULT 0,
    "prize_last_withdraw" timestamp,
    "personal_last_withdraw" timestamp,
    "created_at" timestamp NOT NULL DEFAULT NOW (),
    "updated_at" timestamp
  );

CREATE TABLE
  "transaction" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" BIGINT NOT NULL,
    "source" varchar(31) NOT NULL,
    "status" varchar(15) NOT NULL DEFAULT 'PENDING',
    "type" varchar(15) NOT NULL,
    "amount" numeric(10, 2) NOT NULL,
    "net_amount" numeric(10, 2) NOT NULL,
    "fee" numeric(10, 2),
    "tax" numeric(10, 2),
    "currency" char(3) NOT NULL DEFAULT 'EUR',
    "stripe_payment_intent_id" varchar(255),
    "idempotency_key" varchar(255),
    "pending_reason" varchar(31),
    "transaction_group_id" BIGINT NOT NULL,
    "related_transaction_id" BIGINT,
    "refundable" bool NOT NULL DEFAULT true,
    "visible" bool NOT NULL DEFAULT true,
    "processed_at" timestamp,
    "created_at" timestamp NOT NULL DEFAULT NOW (),
    "updated_at" timestamp
  );

CREATE VIEW
  "wallet_balance" AS
SELECT
  w.account_id,
  COALESCE(
    SUM(
      CASE
        WHEN t.source = 'PRIZE_WALLET'
        AND t.type IN ('PRIZE', 'REFUND')
        AND t.status = 'CONFIRMED' THEN COALESCE(t.amount, 0)
        WHEN t.source = 'PRIZE_WALLET'
        AND t.type IN ('WITHDRAW', 'PAYMENT')
        AND t.status = 'CONFIRMED' THEN - COALESCE(t.amount, 0)
        ELSE 0
      END
    ),
    0
  ) AS prize_balance,
  COALESCE(
    SUM(
      CASE
        WHEN t.source = 'PERSONAL_WALLET'
        AND t.type IN ('FEE', 'REFUND')
        AND t.status = 'CONFIRMED' THEN COALESCE(t.amount, 0)
        WHEN t.source = 'PERSONAL_WALLET'
        AND t.type IN ('WITHDRAW', 'PAYMENT')
        AND t.status = 'CONFIRMED' THEN - COALESCE(t.amount, 0)
        ELSE 0
      END
    ),
    0
  ) AS personal_balance,
  COALESCE(
    SUM(
      CASE
        WHEN t.source = 'INVITE_WALLET'
        AND t.type IN ('INVITE', 'REFUND')
        AND t.status = 'CONFIRMED' THEN COALESCE(t.amount, 0)
        WHEN t.source = 'INVITE_WALLET'
        AND t.type IN ('PAYMENT')
        AND t.status = 'CONFIRMED' THEN - COALESCE(t.amount, 0)
        ELSE 0
      END
    ),
    0
  ) AS invite_balance
FROM
  wallet w
  LEFT JOIN transaction t ON t.account_id = w.account_id
GROUP BY
  w.account_id;

